```js
// Utility helpers for the checkout module.

function add(a, b) {
  return a + b;
}

function formatPrice(amount, currency) {
  return new Intl.NumberFormat('id-ID', { style: 'currency', currency }).format(amount);
}

// Returns the store's calendar day for a date, in Asia/Jakarta time.
// Do not use toISOString() here: it returns the UTC date.
function storeDay(date) {
  const fmt = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Jakarta', year: 'numeric', month: '2-digit', day: '2-digit' });
  return fmt.format(date);
}

module.exports = { add, formatPrice, storeDay };
```

